import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function UserSignin({ handleLogin }) {
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  const createAuth = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://localhost:3597/api/user/login", {
        email,
      });

      alert("Login link sent to your email");

      localStorage.setItem("userToken", res.data.token);
      console.log("Token saved:", res.data.token);

      setMessage("Login link sent successfully!");

      // navigate("/dashboard");  // optional redirect

    } catch (error) {
      alert(error.response?.data?.message || "Please try again");
      setMessage("Invalid email or server error");
    }
  };

  return (
    <div
      className="
      relative flex items-center justify-center
      min-h-screen overflow-hidden
      bg-gradient-to-tr from-[#0a2e2a] via-[#431f79] to-[#230c16]
      bg-[length:300%_300%]
      animate-gradientGlow
    "
    >
      {/* Neon Glow Background */}
      <div
        className="
        absolute inset-0
        bg-gradient-to-r from-cyan-400/60 via-purple-500/60 to-pink-500/40
        blur-3xl
        animate-pulse
      "
      ></div>

      {/* Radial Glow */}
      <div
        className="
        absolute inset-0
        bg-[radial-gradient(circle_at_center,rgba(255,255,255,0.35),transparent_70%)]
      "
      ></div>

      {/* Login Card */}
      <div
        className="
        relative z-10
        w-[380px]
        bg-black/40
        backdrop-blur-md
        border border-white/10
        rounded-xl
        shadow-2xl
        p-8
      "
      >
        <h1 className="text-3xl font-bold text-center text-white mb-6">
          Magic Link Login
        </h1>

        <form onSubmit={createAuth} className="flex flex-col gap-4">
          {/* Email Input */}
          <label className="text-white font-semibold">
            Email
            <input
              type="email"
              placeholder="Enter your email"
              className="
                w-full mt-2 p-3
                rounded-lg
                bg-transparent
                border border-gray-500
                text-white
                outline-none
                focus:border-cyan-400
                transition
              "
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </label>

          {/* Button */}
          <button
            type="submit"
            className="
              mt-4
              py-3
              rounded-lg
              bg-gradient-to-r
              from-cyan-600
              via-purple-500
              to-blue-600
              text-white
              font-semibold
              hover:scale-105
              transition
              shadow-lg
            "
          >
            Send Login Link
          </button>

          {/* Message */}
          {message && (
            <p className="text-center text-sm text-green-400 mt-2">
              {message}
            </p>
          )}
        </form>
      </div>
    </div>
  );
}
